-- One-time load of the company setup from RS 2026.xls and Payroll Details october26.xls (prepared 2026-10-10).
-- Runs only on an empty chart of accounts, so it does nothing once accounts exist.
do $load$
begin
  if exists (select 1 from accounts) then
    raise notice 'rs2026 setup: accounts already exist, skipped';
    return;
  end if;
  update settings set account_map = '{"ap": "L110", "ar": "A130", "dpAdv": "90000", "empAdv": "A160", "retPay": "L120", "salExp": "11001", "salPay": "L180", "siPay": "L165", "socExp": "11010", "socPay": "L160", "taxPay": "L170", "vatIn": "A140", "vatOut": "L140", "whtPay": "L150", "whtRec": "A150"}'::jsonb where id = 1 and account_map = '{}'::jsonb;
  update settings set cats = '{"service":["Design only","Fit-out / execution","Design & build","Supervision"],"type":["Residential","Commercial","Hospitality","Administrative"],"unit":["Penthouse","Chalet","Villa","Apartment","Office"]}'::jsonb where id = 1 and cats = '{}'::jsonb;
end
$load$;
